package com.waelatef.probuilder

import com.android.apksig.ApkSigner
import java.io.File
import java.io.FileInputStream
import java.io.IOException
import java.security.KeyStore
import java.security.PrivateKey
import java.security.cert.X509Certificate

/** Signs a repackaged template using the test-only keystore generated by CI. */
internal object ApkTemplateSigning {
    const val KEYSTORE_ASSET = "probuilder-debug.p12"
    const val KEYSTORE_ALIAS = "androiddebugkey"
    private const val KEYSTORE_PASSWORD = "android"
    private const val KEYSTORE_TYPE = "PKCS12"

    fun sign(unsignedApk: File, signedApk: File, keyStoreFile: File) {
        if (!unsignedApk.isFile || !unsignedApk.canRead()) {
            throw IOException("The modified APK is missing or unreadable.")
        }
        if (!keyStoreFile.isFile || !keyStoreFile.canRead()) {
            throw IOException("The debug signing keystore is missing or unreadable.")
        }

        val password = KEYSTORE_PASSWORD.toCharArray()
        val keyStore = KeyStore.getInstance(KEYSTORE_TYPE)
        FileInputStream(keyStoreFile).use { keyStore.load(it, password) }

        val privateKey = keyStore.getKey(KEYSTORE_ALIAS, password) as? PrivateKey
            ?: throw IOException("The debug keystore does not contain its signing key.")
        val certificate = keyStore.getCertificate(KEYSTORE_ALIAS) as? X509Certificate
            ?: throw IOException("The debug keystore does not contain an X.509 certificate.")

        val signer = ApkSigner.SignerConfig.Builder(
            KEYSTORE_ALIAS,
            privateKey,
            listOf(certificate),
        ).build()

        ApkSigner.Builder(listOf(signer))
            .setInputApk(unsignedApk)
            .setOutputApk(signedApk)
            .setMinSdkVersion(23)
            .setV1SigningEnabled(true)
            .setV2SigningEnabled(true)
            .setV3SigningEnabled(true)
            .build()
            .sign()
    }
}
